/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3margin {	public static final class Attr {		public static final String margin = "margin";	}	public Value margin(String shorthand) {		return new Value().name(Attr.margin).text(shorthand);	}	public Value margin(String side, String pixels) {		return new Value().name(Attr.margin + "-" + side).text(pixels);	}	public Value top(String pixels) {		return new Value().name(Attr.margin + "-top").text(pixels);	}	public Value right(String pixels) {		return new Value().name(Attr.margin + "-right").text(pixels);	}	public Value bottom(String pixels) {		return new Value().name(Attr.margin + "-bottom").text(pixels);	}	public Value left(String pixels) {		return new Value().name(Attr.margin + "-left").text(pixels);	}	public Value auto() {		return new Value().name(Attr.margin).text("auto");	}	public Value autoLeft() {		return new Value().name(Attr.margin + "-left").text("auto");	}	public Value autoRight() {		return new Value().name(Attr.margin + "-right").text("auto");	}}